/**
 * Wendy's oil paintings. Only her own work belongs here.
 *
 * To add a painting:
 *   1. Photograph it straight-on, evenly lit, cropped to the canvas.
 *   2. Put the file in content/paintings/ and run `npm run images`.
 *   3. Add an entry with `image: '<key>'`. Leave out anything unknown —
 *      a missing title is shown as "Untitled".
 */
export interface Painting {
  id: string
  /** Asset key from src/data/image-manifest.json (generated by `npm run images`). */
  image?: string
  thumbnail?: string
  title?: Text
  year?: string
  /** e.g. { en: 'Oil on canvas', de: 'Öl auf Leinwand', zh: '布面油画' } */
  medium?: Text
  /** e.g. '40 × 50 cm' */
  dimensions?: string
  description?: Text
  /** Plain description of what the picture shows (screen readers). Not a title. */
  alt?: Text
  /** Placeholder only: width / height of the empty canvas. */
  placeholder?: { ratio: number }
}

